// Verifies that `rotate(a, offset)` returns a new Vec of the same length as `a`
// and that its elements are exactly a left‐rotation of `a` by `offset` positions.
//
// We must guard the modulo by zero in the specification, so we define
//   k_spec = if a.len() == 0 { 0 } else { offset % a.len() }
// then ensure that for all valid indices i, result[i] == a[(i + k_spec) % a.len()].
#[requires(true)]
#[ensures(result.len() == a.len())]
#[ensures(
    // k_spec = effective rotation amount in [0, n), or 0 if n == 0
    let k_spec = if a.len() == 0 { 0 } else { offset % a.len() };
    forall(|i: usize| i < a.len() ==>
        result[i] == a[(i + k_spec) % a.len()]
    )
)]
pub fn rotate(a: &[i32], offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return Vec::new();
    }
    // Compute the effective rotation within [0, n)
    let k = offset % n;
    // Build the rotated array by taking the tail [k..n) then the head [0..k)
    a[k..]
        .iter()
        .chain(&a[..k])
        .cloned()
        .collect()
}

